<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ApiError, describeError, request, workspacePath, type Workspace } from './api'
import type { RuntimeEvidenceScope, RuntimeEvidenceSource } from './runtime-evidence-scope'
const props=defineProps<{workspace:Workspace;required?:boolean}>();const emit=defineEmits<{change:[scope:RuntimeEvidenceScope|undefined,valid:boolean,enabled:boolean];sessionExpired:[]}>()
const enabled=ref(!!props.required),sources=ref<RuntimeEvidenceSource[]>([]),error=ref(''),sourceId=ref('');const active=new AbortController()
function localDate(date:Date){return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
const form=reactive({method:'',route:'',subjectRef:'',clientIp:'',from:localDate(new Date(Date.now()-86400000)),to:localDate(new Date())});const source=computed(()=>sources.value.find(s=>String(s.id)===sourceId.value));const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone
function publish(){const from=new Date(form.from),to=new Date(form.to);const valid=!!source.value&&Number.isFinite(from.getTime())&&Number.isFinite(to.getTime())&&from<to;emit('change',enabled.value&&valid?{sourceId:Number(sourceId.value),service:source.value!.service,...(form.method?{method:form.method}:{}),...(form.route.trim()?{route:form.route.trim()}:{}),...(form.subjectRef.trim()?{subjectRef:form.subjectRef.trim()}:{}),...(form.clientIp.trim()?{clientIp:form.clientIp.trim()}:{}),from:from.toISOString(),to:to.toISOString()}:undefined,!enabled.value||valid,enabled.value)}
watch([enabled,sourceId,()=>({...form})],publish,{deep:true})
onMounted(async()=>{try{const result=await request<{items:RuntimeEvidenceSource[]}>(workspacePath(props.workspace.slug)+'/api-security/runtime/sources',{signal:active.signal});sources.value=result.items.filter(s=>!s.revokedAt);publish()}catch(e){if(!active.signal.aborted){if(e instanceof ApiError&&e.status===401)emit('sessionExpired');else error.value=describeError(e)}}});onBeforeUnmount(()=>active.abort())
</script>
<template><section class="runtime-evidence-scope"><label v-if="!required" class="runtime-scope-toggle"><input v-model="enabled" type="checkbox">按运行时来源、用户/IP与指定时间检查</label><p v-if="error" class="message message-error" role="alert">{{error}}</p><template v-if="enabled"><p>仅采用所选来源已记录的观察；用户使用来源提供的去标识subjectRef，不从IP推断身份。时间按{{timezone}}填写并转为UTC提交。</p><div class="runtime-scope-fields"><label>当前运行时来源<select v-model="sourceId"><option value="">请选择已授权来源</option><option v-for="s in sources" :key="s.id" :value="String(s.id)">{{s.name}} · {{s.service}} · #{{s.id}}</option></select></label><label>服务别名<input :value="source?.service||''" readonly placeholder="随来源确定"></label><label>请求方法<select v-model="form.method"><option value="">全部方法</option><option v-for="method in ['GET','POST','PUT','PATCH','DELETE','HEAD','OPTIONS','TRACE']" :key="method">{{method}}</option></select></label><label>路由模板（可选）<input v-model="form.route" maxlength="200" placeholder="/orders/{id}"></label><label>用户subjectRef（可选）<input v-model="form.subjectRef" maxlength="160" placeholder="来源内去标识主体引用"></label><label>客户端IP（可选）<input v-model="form.clientIp" maxlength="64" placeholder="精确IP，不推断人员"></label><label>开始时间<input v-model="form.from" type="datetime-local" required></label><label>结束时间<input v-model="form.to" type="datetime-local" required></label></div><p v-if="!sources.length">尚无可用运行时来源。请先在API安全中登记来源并接入真实观察。</p></template></section></template>
<style scoped>.runtime-evidence-scope{border:1px solid var(--line);border-radius:8px;padding:15px 18px;background:var(--surface-subtle);display:grid;gap:12px}.runtime-scope-toggle{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600}.runtime-evidence-scope p{font-size:12px;color:var(--secondary);line-height:1.8;margin:0}.runtime-scope-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.runtime-scope-fields label{display:grid;gap:7px;font-size:12px;min-width:0}.runtime-scope-fields input,.runtime-scope-fields select{font:inherit;background:var(--surface);color:var(--ink);border:1px solid var(--input-line);padding:8px 9px;border-radius:6px;width:100%;min-width:0}@media(max-width:1050px){.runtime-scope-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.runtime-scope-fields{grid-template-columns:1fr}}</style>
